DROP TABLE IF EXISTS `tb_active_course_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_active_course_log` (
  `active_course_log_seq` int NOT NULL AUTO_INCREMENT,
  `active_detail_log_seq` varchar(20) DEFAULT NULL,
  `course_seq` int DEFAULT NULL COMMENT '강좌 순차번호',
  `conn_way` varchar(1) DEFAULT NULL COMMENT '접속방법[210]',
  `login_yn` varchar(1) DEFAULT NULL COMMENT '로그인 여부',
  `time_on_page` varchar(10) DEFAULT NULL COMMENT '머문 시간 [즉시, 30초, 3분, 5분, 10분]',
  `reg_dts` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '등록 일시',
  `upd_dts` datetime DEFAULT NULL COMMENT '수정 일시',
  `sum_course_cnt` int DEFAULT NULL,
  PRIMARY KEY (`active_course_log_seq`)
) ENGINE=InnoDB AUTO_INCREMENT=787 DEFAULT CHARSET=utf8mb3 COMMENT='강좌 활동 기록 로그';
