--
-- Table structure for table `tb_active_log`
--

DROP TABLE IF EXISTS `tb_active_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_active_log` (
  `active_log_seq` int NOT NULL AUTO_INCREMENT,
  `conn_ip` varchar(20) DEFAULT NULL COMMENT '접속 IP',
  `conn_uri` varchar(100) DEFAULT NULL COMMENT '접속 URI',
  `conn_way` varchar(1) NOT NULL COMMENT '접속방법[210]',
  `login_yn` varchar(1) DEFAULT NULL COMMENT '로그인 여부',
  `user_id` varchar(20) DEFAULT NULL COMMENT '사용자 ID',
  `time_on_page` varchar(10) DEFAULT NULL COMMENT '머문 시간 [즉시, 30초, 3분, 5분, 10분]',
  `reg_dts` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '등록 일시',
  `upd_dts` datetime DEFAULT NULL COMMENT '수정 일시',
  `menu_seq` varchar(10) DEFAULT NULL COMMENT '메뉴 시퀀스',
  `menu_nm` varchar(20) DEFAULT NULL COMMENT '메뉴명',
  `log_gb` varchar(5) DEFAULT NULL COMMENT '로그구분[071]',
  `info_gb` varchar(5) DEFAULT NULL COMMENT '대상정보 구분[072]',
  `sum_cnt` int DEFAULT NULL COMMENT '기록합계',
  PRIMARY KEY (`active_log_seq`)
) ENGINE=InnoDB AUTO_INCREMENT=2744 DEFAULT CHARSET=utf8mb3 COMMENT='활동 기록 로그';
/*!40101 SET character_set_client = @saved_cs_client */;

