DROP TABLE IF EXISTS `tb_board`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_board` (
  `BOARD_SEQ` int unsigned NOT NULL AUTO_INCREMENT COMMENT '게시글 번호',
  `BOARD_RE_REF` int DEFAULT NULL COMMENT '글의 그룹 번호',
  `BOARD_RE_LEV` int DEFAULT NULL COMMENT '답변 글의 깊이',
  `BOARD_RE_SEQ` int DEFAULT NULL COMMENT '답변 글의 순서',
  `BOARD_WRITER` varchar(20) DEFAULT NULL COMMENT '게시글의 작성자',
  `BOARD_SUBJECT` varchar(50) DEFAULT NULL COMMENT '게시글의 제목',
  `BOARD_CONTENT` varchar(2000) DEFAULT NULL COMMENT '게시글의 내용',
  `BOARD_HITS` int unsigned NOT NULL DEFAULT '0' COMMENT '게시글의 조회수',
  `DEL_YN` varchar(1) NOT NULL DEFAULT 'N' COMMENT '삭제유무',
  `INS_USER_ID` varchar(20) DEFAULT NULL COMMENT '입력자ID',
  `INS_DATE` datetime DEFAULT NULL COMMENT '입력일시',
  `UPD_USER_ID` varchar(20) DEFAULT NULL COMMENT '수정자ID',
  `UPD_DATE` datetime DEFAULT NULL COMMENT '수정일시',
  PRIMARY KEY (`BOARD_SEQ`)
) ENGINE=InnoDB AUTO_INCREMENT=10097 DEFAULT CHARSET=utf8mb3 COMMENT='게시판';
