--
-- Table structure for table `tb_code`
--

DROP TABLE IF EXISTS `tb_code`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_code` (
  `code_seq` int unsigned NOT NULL AUTO_INCREMENT COMMENT '코드 순차번호',
  `group_code` varchar(20) DEFAULT NULL COMMENT '그룹 코드',
  `code` varchar(20) DEFAULT NULL COMMENT '코드',
  `sort_no` int unsigned DEFAULT NULL COMMENT '순번',
  `code_nm` varchar(500) DEFAULT NULL COMMENT '코드 명',
  `display_nm` varchar(500) DEFAULT NULL COMMENT '노출 명',
  `code_descr` varchar(500) DEFAULT NULL COMMENT '코드 설명',
  `code_sort_no` int DEFAULT NULL COMMENT '코드 순번',
  `parnts_code` varchar(20) DEFAULT NULL,
  `use_yn` char(1) DEFAULT NULL COMMENT '사용 여부',
  `default_yn` char(1) DEFAULT NULL COMMENT '기본 여부',
  `reference_code` varchar(20) DEFAULT NULL COMMENT '참조 코드',
  `reg_dts` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '등록 일시',
  `reg_user` int unsigned DEFAULT NULL COMMENT '등록자',
  `upd_dts` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '수정 일시',
  `upd_user` int unsigned DEFAULT NULL COMMENT '수정자',
  PRIMARY KEY (`code_seq`),
  UNIQUE KEY `PK_TB_code` (`code_seq`),
  KEY `IX_TB_code_01` (`group_code`,`code`)
) ENGINE=InnoDB AUTO_INCREMENT=621 DEFAULT CHARSET=utf8mb3 COMMENT='코드';
/*!40101 SET character_set_client = @saved_cs_client */;

