DROP TABLE IF EXISTS `tb_send`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_send` (
  `send_seq` int unsigned NOT NULL AUTO_INCREMENT COMMENT '발송 순차번호',
  `course_open_seq` int unsigned DEFAULT NULL COMMENT '과정 개설 순차번호',
  `template_seq` int unsigned DEFAULT NULL COMMENT '템플릿 순차번호',
  `title` varchar(500) DEFAULT NULL COMMENT '제목',
  `contents` mediumtext COMMENT '내용',
  `send_state` varchar(20) DEFAULT NULL COMMENT '발송상태[053]',
  `mail_send_state` varchar(20) DEFAULT NULL COMMENT '메일 발송상태[053]',
  `send_type` varchar(20) DEFAULT NULL COMMENT '발송타입[052]',
  `send_dt_gb` varchar(20) DEFAULT NULL COMMENT '발송일구분[057]',
  `send_dt` datetime DEFAULT NULL COMMENT '발송 일자',
  `send_time` varchar(500) DEFAULT NULL COMMENT '발송 시간',
  `del_yn` char(1) DEFAULT NULL COMMENT '삭제 여부',
  `reg_dts` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '등록 일시',
  `reg_user` int unsigned DEFAULT NULL COMMENT '등록자',
  `upd_dts` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '수정 일시',
  `upd_user` int unsigned DEFAULT NULL COMMENT '수정자',
  `email` varchar(45) DEFAULT NULL,
  `user_seq` varchar(45) DEFAULT NULL,
  PRIMARY KEY (`send_seq`),
  UNIQUE KEY `PK_TB_send` (`send_seq`),
  KEY `IF1_TB_send` (`template_seq`),
  KEY `IF2_TB_send` (`course_open_seq`)
) ENGINE=InnoDB AUTO_INCREMENT=233 DEFAULT CHARSET=utf8mb3 COMMENT='발송';
