INSERT INTO `tb_send` VALUES (224,NULL,7,'[바디프랜드 학습관리시스템] 학습 수료 안내','<div style=\"padding:15px; background-color:#f9f9f9\">\n    <div style=\"max-width: 600px; margin: 0 auto;\"> <img src=\"https://hrd.bodyfriend.com/lms/dist/lms/images/logo_gnb.svg\" style=\"margin-top:50px;\">\n        <table width=\"100%\" style=\"background-color: #fff;border: solid 1px #e6e6e6; margin-top:30px; font-family: AppleSDGothic, 나눔고딕, Dotum, Baekmuk Dotum, Undotum, Latin font, sans-serif;\">\n            <tbody>\n                <tr>\n                    <td style=\"padding: 30px 20px;background: #fff;\">\n                        <!-- 메일내용 시작 -->\n                        <table width=\"100%\" style=\"font-size:15px;border: none;\">\n                            <tbody>\n                                <tr style=\"border: none;\">\n                                    <td style=\"background: #fff;border: none;\"> <strong style=\"font-size:20px; float:left\">학습 수료 안내</strong> <span style=\"float:right; color:#808080\">학습관리시스템</span> </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                        <table width=\"100%\" style=\"font-size:15px; border-top:1px solid #515256; margin-top: 10px;\">\n                            <tbody style=\"border: none;\">\n                                <tr style=\"border: none;\">\n                                    <td style=\"background: #fff;border: none;padding-top: 20px;\">\n                                        안녕하세요, 인재개발팀입니다.<br /><br />\n                                        ${이름}$님, 과정 수료 축하드립니다.<br />\n                                        수료증은 내 강의실에서 출력 가능합니다.<br /><br />\n\n                                        <table width=\"100%\" style=\"border-spacing: 0; border:1px solid #ccced0\">\n                                            <tbody>\n                                                <tr>\n                                                    <td style=\"width:70px; padding:14px; background: #f7f7f7;\">과정명</td>\n                                                    <td style=\"padding:14px 20px;\">${과정명}$</td>\n                                                </tr>\n                                                <tr>\n                                                    <td style=\"width:70px; padding:14px; background: #f7f7f7; border-top:1px solid #ccced0;\">수강기간</td>\n                                                    <td style=\"border-top:1px solid #ccced0; padding:14px 20px;\">${수강기간}$</td>\n                                                </tr>\n                                                <tr>\n                                                    <td style=\"width:70px; border-top:1px solid #ccced0; padding:14px; background: #f7f7f7;\">수료여부</td>\n                                                    <td style=\"border-top:1px solid #ccced0; padding:14px 20px;\">${수료여부}$</td>\n                                                </tr>\n                                            </tbody>\n                                        </table>\n                                        <br />\n                                        문의사항은 사이트 내 1:1 문의하기 또는 Q&A 게시판에 남겨주시기 바랍니다.<br /><br />\n                                        감사합니다.\n                                    </td>\n                                </tr>\n                                <tr style=\"text-align: center;border: none;\">\n                                    <td style=\"padding-top:20px; background: #fff;border: none;\">\n                                        <span style=\"padding:14px 10px; color:#808080;border-radius: 5px;border: solid 1px #808080; text-decoration: none; font-weight: 500; display: inline-block;margin:10px 5px;min-width: 130px;\"><a href=\"http://bodyfriend.kotech.kr/lms/my/lecture/main/get/index.do\">내 강의실 바로가기</a>\n                                        </span>\n                                        <span style=\"padding:14px 10px; color:#808080;border-radius: 5px;border: solid 1px #808080; text-decoration: none; font-weight: 500; display: inline-block;margin:10px 5px;min-width: 130px;\"><a href=\"http://bodyfriend.kotech.kr/lms/support/inquiry/mod/insert.do\">1:1 문의하기</a>\n                                        </span>\n                                    </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </td>\n                </tr>\n            </tbody>\n        </table> <!-- footer -->\n        <table width=\"100%\">\n            <tbody>\n                <tr style=\"border: none;\">\n                    <td style=\"color:#808080;font-size:11px; height:40px;background: #f9f9f9;border: none;padding-top: 20px;padding-bottom: 15px;\"> 본 메일은 발신 전용으로, 회신하실 경우 답변되지 않습니다.<br> </td>\n                </tr>\n                <tr style=\"height: 90px;border: none;\">\n                    <td style=\"background: #f9f9f9;color:#808080;font-size:10px; border-top:1px solid #f0f0f0;border-bottom: none;border-left: none;border-right: none;padding-top: 10px;\"> (주)바디프랜드 | 대표이사 : 박상현<br> 서울특별시 강남구 양재천로 163 바디프랜드 도곡타워<br>대표번호: 02-3448-8980<br> Copyright ⓒ BODYFRIEND, Inc. All Rights reserved. </td>\n                </tr>\n            </tbody>\n        </table>\n    </div>\n</div>','S',NULL,'M',NULL,'2023-03-29 17:02:41',NULL,NULL,NULL,1,'2023-03-29 17:02:44',NULL,'ffin9@naver.com',NULL),(225,NULL,1,'Default','<div style=\"padding:15px; background-color:#f9f9f9\"><div style=\"max-width: 600px; margin: 0 auto;\"><img src=\"https://www.bodyfriend.co.kr/img/main_img/main_logo_sub_2018.png\" style=\"margin-top:50px;\"><table width=\"100%\" style=\"background-color: #fff;border: solid 1px #e6e6e6; margin-top:30px; font-family: AppleSDGothic, 나눔고딕, Dotum, Baekmuk Dotum, Undotum, Latin font, sans-serif;\"><tbody><tr><td style=\"padding: 30px 20px;background: #fff;\"><!-- 메일내용 시작 --><table width=\"100%\" style=\"font-size:15px;border: none;\"><tbody><tr style=\"border: none;\"><td style=\"background: #fff;border: none;\"><strong style=\"font-size:20px; float:left\">${메일제목 입력}$</strong><span style=\"float:right; color:#808080\">학습관리시스템</span></td></tr></tbody></table><table width=\"100%\" style=\"font-size:15px; border-top:1px solid #515256; margin-top: 10px;\"><tbody style=\"border: none;\"><tr style=\"border: none;\"><td style=\"background: #fff;border: none;padding-top: 20px;\"><br><br>${메일 내용 입력}$</td></tr><tr style=\"text-align: center;border: none;\"><td style=\"padding-top:20px; background: #fff;border: none;\"><br></td></tr></tbody></table></td></tr></tbody></table><!-- footer --><table width=\"100%\"><tbody><tr style=\"border: none;\"><td style=\"color:#808080;font-size:11px; height:40px;background: #f9f9f9;border: none;padding-top: 20px;padding-bottom: 15px;\">본 메일은 발신 전용으로, 회신하실 경우 답변되지 않습니다.<br></td></tr><tr style=\"height: 90px;border: none;\"><td style=\"background: #f9f9f9;color:#808080;font-size:10px; border-top:1px solid #f0f0f0;border-bottom: none;border-left: none;border-right: none;padding-top: 10px;\">(주)바디프랜드 | 대표이사 : 박상현<br>서울특별시 강남구 양재천로 163 바디프랜드 도곡타워<br>대표번호: 02-3448-8980<br>Copyright ⓒ BODYFRIEND, Inc. All Rights reserved.</td></tr></tbody></table></div></div>','S',NULL,'M',NULL,'2023-03-29 17:28:40',NULL,NULL,NULL,1,'2023-03-29 17:28:42',NULL,'ffin9@naver.com',NULL),(226,NULL,7,'[바디프랜드 학습관리시스템] 학습 수료 안내','<div style=\"padding:15px; background-color:#f9f9f9\">\n    <div style=\"max-width: 600px; margin: 0 auto;\"> <img src=\"https://hrd.bodyfriend.com/lms/dist/lms/images/logo_gnb.svg\" style=\"margin-top:50px;\">\n        <table width=\"100%\" style=\"background-color: #fff;border: solid 1px #e6e6e6; margin-top:30px; font-family: AppleSDGothic, 나눔고딕, Dotum, Baekmuk Dotum, Undotum, Latin font, sans-serif;\">\n            <tbody>\n                <tr>\n                    <td style=\"padding: 30px 20px;background: #fff;\">\n                        <!-- 메일내용 시작 -->\n                        <table width=\"100%\" style=\"font-size:15px;border: none;\">\n                            <tbody>\n                                <tr style=\"border: none;\">\n                                    <td style=\"background: #fff;border: none;\"> <strong style=\"font-size:20px; float:left\">학습 수료 안내</strong> <span style=\"float:right; color:#808080\">학습관리시스템</span> </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                        <table width=\"100%\" style=\"font-size:15px; border-top:1px solid #515256; margin-top: 10px;\">\n                            <tbody style=\"border: none;\">\n                                <tr style=\"border: none;\">\n                                    <td style=\"background: #fff;border: none;padding-top: 20px;\">\n                                        안녕하세요, 인재개발팀입니다.<br /><br />\n                                        유정현님, 과정 수료 축하드립니다.<br />\n                                        수료증은 내 강의실에서 출력 가능합니다.<br /><br />\n\n                                        <table width=\"100%\" style=\"border-spacing: 0; border:1px solid #ccced0\">\n                                            <tbody>\n                                                <tr>\n                                                    <td style=\"width:70px; padding:14px; background: #f7f7f7;\">과정명</td>\n                                                    <td style=\"padding:14px 20px;\"></td>\n                                                </tr>\n                                                <tr>\n                                                    <td style=\"width:70px; padding:14px; background: #f7f7f7; border-top:1px solid #ccced0;\">수강기간</td>\n                                                    <td style=\"border-top:1px solid #ccced0; padding:14px 20px;\">~</td>\n                                                </tr>\n                                                <tr>\n 