DROP TABLE IF EXISTS `tb_send_target`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_send_target` (
  `send_target_seq` int unsigned NOT NULL AUTO_INCREMENT COMMENT '발송 대상 순차번호',
  `send_seq` int unsigned DEFAULT NULL COMMENT '발송 순차번호',
  `template_seq` int unsigned DEFAULT NULL COMMENT '템플릿 순차번호',
  `user_seq` int unsigned DEFAULT NULL COMMENT '회원 순차번호',
  `send_info` varchar(20) DEFAULT NULL COMMENT '발송 정보',
  `send_gb` varchar(20) DEFAULT NULL COMMENT '발송구분[051]',
  `send_state` varchar(20) DEFAULT NULL COMMENT '발송상태[053]',
  `template_id` varchar(500) DEFAULT NULL COMMENT '템플릿 id',
  `title` varchar(500) DEFAULT NULL COMMENT '제목',
  `contents` mediumtext COMMENT '내용',
  `send_dts` datetime DEFAULT NULL COMMENT '발송 일시',
  `view_dts` datetime DEFAULT NULL COMMENT '조회 일시',
  `reg_dts` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '등록 일시',
  `reg_user` int unsigned DEFAULT NULL COMMENT '등록자',
  `upd_dts` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '수정 일시',
  `upd_user` int unsigned DEFAULT NULL COMMENT '수정자',
  PRIMARY KEY (`send_target_seq`),
  UNIQUE KEY `PK_TB_send_target` (`send_target_seq`),
  KEY `IF2_TB_send_target` (`send_seq`),
  KEY `IF3_TB_send_target` (`template_seq`)
) ENGINE=InnoDB AUTO_INCREMENT=15358 DEFAULT CHARSET=utf8mb3 COMMENT='발송 대상';
