DROP TABLE IF EXISTS `ts_cmmn_attach_file`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ts_cmmn_attach_file` (
  `file_seq` int NOT NULL AUTO_INCREMENT COMMENT '파일 순차번호',
  `file_reg_gb` varchar(20) NOT NULL COMMENT '파일등록구분',
  `tar_info_pk` varchar(200) NOT NULL COMMENT '대상정보PK',
  `expo_sort` int DEFAULT '0' COMMENT '노출 순서',
  `orgin_filenm` varchar(200) DEFAULT NULL COMMENT '원본 파일명',
  `save_filenm` varchar(200) DEFAULT NULL COMMENT '저장 파일명',
  `file_save_path` varchar(200) DEFAULT NULL COMMENT '파일저장 경로',
  `file_ext` varchar(20) DEFAULT NULL COMMENT '파일 확장자',
  `file_size` int DEFAULT NULL COMMENT '파일 사이즈',
  `dwld_cnt` int DEFAULT '0' COMMENT '다운로드 횟수',
  `del_yn` char(1) DEFAULT 'N' COMMENT '삭제여부',
  PRIMARY KEY (`file_seq`),
  KEY `IX_ts_cmmn_attach_file_01` (`file_reg_gb`,`tar_info_pk`)
) ENGINE=InnoDB AUTO_INCREMENT=4590 DEFAULT CHARSET=utf8mb3 COMMENT='공통 첨부 파일';
/*!40101 SET character_set_client = @saved_cs_client */;

